#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Keepalive ping batcher for A2A Mesh.
Batches keepalive pings into 30-second windows to reduce P2P chatter.
"""

import time
import threading
import logging
import json
from dataclasses import dataclass, field
from typing import Dict, List, Callable, Optional, Set
from collections import defaultdict

logger = logging.getLogger("a2a_mesh.keepalive_batcher")

BATCH_WINDOW_SECONDS = 30


@dataclass
class PendingPing:
    """Represents a single pending keepalive ping."""
    peer_id: str
    timestamp: float
    payload: Dict = field(default_factory=dict)


@dataclass
class BatchedPingMessage:
    """A batched keepalive message containing multiple pings."""
    batch_id: str
    window_start: float
    window_end: float
    pings: List[Dict]

    def to_dict(self) -> Dict:
        return {
            "type": "keepalive_batch",
            "batch_id": self.batch_id,
            "window_start": self.window_start,
            "window_end": self.window_end,
            "ping_count": len(self.pings),
            "pings": self.pings,
        }

    def to_json(self) -> str:
        return json.dumps(self.to_dict())

    @classmethod
    def from_dict(cls, data: Dict) -> "BatchedPingMessage":
        return cls(
            batch_id=data["batch_id"],
            window_start=data["window_start"],
            window_end=data["window_end"],
            pings=data.get("pings", []),
        )


class KeepaliveBatcher:
    """
    Batches individual keepalive pings into 30-second windows.

    Instead of sending a ping immediately for each peer, pings are collected
    during a 30-second window and sent as a single batched message.
    This significantly reduces P2P chatter.
    """

    def __init__(
        self,
        window_seconds: float = BATCH_WINDOW_SECONDS,
        sender_callback: Optional[Callable[[BatchedPingMessage], None]] = None,
        auto_start: bool = True,
    ):
        self.window_seconds = window_seconds
        self.sender_callback = sender_callback
        self._pending: Dict[str, PendingPing] = {}
        self._lock = threading.Lock()
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._window_start: float = 0.0
        self._batch_counter: int = 0
        self._received_batches: Set[str] = set()
        self._max_received_batches = 1000
        self._responded_peers: Set[str] = set()

        if auto_start:
            self.start()

    def start(self) -> None:
        """Start the batcher background thread."""
        if self._running:
            logger.warning("KeepaliveBatcher already running")
            return
        self._running = True
        self._window_start = time.time()
        self._thread = threading.Thread(target=self._run_loop, daemon=True, name="keepalive-batcher")
        self._thread.start()
        logger.info(f"KeepaliveBatcher started with {self.window_seconds}s window")

    def stop(self) -> None:
        """Stop the batcher and flush remaining pings."""
        self._running = False
        if self._thread:
            self._thread.join(timeout=5)
        self._flush()
        logger.info("KeepaliveBatcher stopped")

    def schedule_ping(self, peer_id: str, payload: Optional[Dict] = None) -> None:
        """
        Schedule a keepalive ping for a peer. The ping will be batched
        and sent at the end of the current 30-second window.
        """
        with self._lock:
            self._pending[peer_id] = PendingPing(
                peer_id=peer_id,
                timestamp=time.time(),
                payload=payload or {},
            )
            logger.debug(f"Scheduled keepalive ping for peer {peer_id} (pending: {len(self._pending)})")

    def _run_loop(self) -> None:
        """Main loop that flushes batches every window_seconds."""
        while self._running:
            elapsed = time.time() - self._window_start
            sleep_time = self.window_seconds - elapsed
            if sleep_time > 0:
                time.sleep(min(sleep_time, 1.0))
                continue
            self._flush()
            self._window_start = time.time()

    def _flush(self) -> None:
        """Flush all pending pings as a single batched message."""
        with self._lock:
            if not self._pending:
                return
            pings = []
            for peer_id, pp in self._pending.items():
                pings.append({
                    "peer_id": peer_id,
                    "timestamp": pp.timestamp,
                    "payload": pp.payload,
                })
            self._pending.clear()
            self._batch_counter += 1
            batch_id = f"kb_{int(self._window_start)}_{self._batch_counter}"

        batch = BatchedPingMessage(
            batch_id=batch_id,
            window_start=self._window_start,
            window_end=time.time(),
            pings=pings,
        )

        logger.info(f"Flushing keepalive batch {batch_id} with {len(pings)} pings")

        if self.sender_callback:
            try:
                self.sender_callback(batch)
            except Exception as e:
                logger.error(f"Error sending keepalive batch: {e}")

    def receive_batch(self, batch_data: Dict, responder_callback: Optional[Callable[[str, Dict], None]] = None) -> Optional[BatchedPingMessage]:
        """
        Process an incoming batched keepalive message.

        Returns the parsed BatchedPingMessage, or None if duplicate/invalid.
        If responder_callback is provided, sends pong responses for each ping.
        """
        try:
            batch = BatchedPingMessage.from_dict(batch_data)
        except (KeyError, TypeError) as e:
            logger.warning(f"Invalid keepalive batch received: {e}")
            return None

        if batch.batch_id in self._received_batches:
            logger.debug(f"Duplicate keepalive batch {batch.batch_id}, ignoring")
            return None

        self._received_batches.add(batch.batch_id)
        if len(self._received_batches) > self._max_received_batches:
            self._received_batches = set(list(self._received_batches)[-self._max_received_batches:])

        logger.info(f"Received keepalive batch {batch.batch_id} with {len(batch.pings)} pings")

        if responder_callback:
            for ping in batch.pings:
                peer_id = ping.get("peer_id", "unknown")
                if peer_id not in self._responded_peers:
                    pong = {
                        "type": "keepalive_pong",
                        "batch_id": batch.batch_id,
                        "peer_id": peer_id,
                        "timestamp": time.time(),
                    }
                    try:
                        responder_callback(peer_id, pong)
                    except Exception as e:
                        logger.error(f"Error sending pong to {peer_id}: {e}")
                    self._responded_peers.add(peer_id)

        return batch

    def get_stats(self) -> Dict:
        """Return current batcher statistics."""
        with self._lock:
            return {
                "pending_pings": len(self._pending),
                "window_seconds": self.window_seconds,
                "batches_sent": self._batch_counter,
                "received_batches_tracked": len(self._received_batches),
                "running": self._running,
                "elapsed_in_window": time.time() - self._window_start,
            }

    def flush_now(self) -> None:
        """Manually trigger a flush of pending pings."""
        self._flush()
        self._window_start = time.time()


# --- Demo / standalone execution ---

class MockTransport:
    """Mock transport for demonstration purposes."""
    def __init__(self):
        self.sent_messages: List[str] = []
        self.lock = threading.Lock()

    def send(self, batch: BatchedPingMessage) -> None:
        msg = batch.to_json()
        with self.lock:
            self.sent_messages.append(msg)
        print(f"  [TRANSPORT] Sent batch {batch.batch_id} ({len(batch.pings)} pings)")

    def respond(self, peer_id: str, pong: Dict) -> None:
        print(f"  [TRANSPORT] Sent pong to {peer_id}: {json.dumps(pong)}")


def main():
    """Demonstrate the keepalive batcher with simulated peers."""
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
    )

    print("=" * 60)
    print("A2A Mesh — Keepalive Ping Batcher Demo")
    print(f"Window size: {BATCH_WINDOW_SECONDS}s")
    print("=" * 60)

    transport = MockTransport()

    # Create batcher with short window for demo (5 seconds)
    DEMO_WINDOW = 5
    batcher = KeepaliveBatcher(
        window_seconds=DEMO_WINDOW,
        sender_callback=transport.send,
        auto_start=True,
    )

    # Simulate scheduling pings for multiple peers
    peers = ["peer_alice", "peer_bob", "peer_carol", "peer_dave", "peer_eve"]

    print(f"\n1. Scheduling {len(peers)} keepalive pings...")
    for peer_id in peers:
        batcher.schedule_ping(peer_id, payload={"last_seen": time.time()})
        print(f"   Scheduled ping for {peer_id}")

    stats = batcher.get_stats()
    print(f"\n   Stats: {json.dumps(stats, indent=2)}")

    print(f"\n2. Waiting {DEMO_WINDOW + 1}s for batch window to flush...")
    time.sleep(DEMO_WINDOW + 1)

    print(f"\n3. Sent messages: {len(transport.sent_messages)}")
    for msg in transport.sent_messages:
        data = json.loads(msg)
        print(f"   Batch {data['batch_id']}: {data['ping_count']} pings")
        for p in data["pings"]:
            print(f"     -> {p['peer_id']}")

    # Simulate receiving a batch
    print("\n4. Simulating incoming batch from remote node...")
    incoming_batch = {
        "type": "keepalive_batch",
        "batch_id": "kb_remote_001",
        "window_start": time.time() - 30,
        "window_end": time.time(),
        "pings": [
            {"peer_id": "remote_node_1", "timestamp": time.time() - 15, "payload": {}},
            {"peer_id": "remote_node_2", "timestamp": time.time() - 10, "payload": {}},
            {"peer_id": "remote_node_3", "timestamp": time.time() - 5, "payload": {}},
        ],
    }

    received = batcher.receive_batch(incoming_batch, responder_callback=transport.respond)
    if received:
        print(f"   Processed incoming batch with {len(received.pings)} pings")

    # Test duplicate detection
    print("\n5. Testing duplicate batch detection...")
    dup = batcher.receive_batch(incoming_batch)
    print(f"   Duplicate result: {dup}")

    # Schedule more pings and flush manually
    print("\n6. Scheduling more pings and flushing manually...")
    for i in range(3):
        batcher.schedule_ping(f"peer_new_{i}")

    batcher.flush_now()

    print(f"\n7. Final stats: {json.dumps(batcher.get_stats(), indent=2)}")

    print("\n8. Stopping batcher...")
    batcher.stop()

    print(f"\nTotal messages sent: {len(transport.sent_messages)}")
    print("\n" + "=" * 60)
    print("Demo complete. The batcher reduces P2P keepalive chatter by")
    print(f"combining individual pings into {BATCH_WINDOW_SECONDS}s windows.")
    print("=" * 60)


if __name__ == "__main__":
    main()